using UnityEngine;using System.Linq;using Newtonsoft.Json;public class Script{public static string Main(){if(!Application.dataPath.Replace('\\','/').EndsWith("/.ai/combat-magic/unity-reference/Assets"))throw new System.Exception("Owned reference only");var go=new GameObject("Native radius probe");try{var ps=go.AddComponent<ParticleSystem>();ps.Stop(false,ParticleSystemStopBehavior.StopEmittingAndClear);var m=ps.main;m.maxParticles=4096;m.startSpeed=0;m.startLifetime=10;var em=ps.emission;em.enabled=false;var sh=ps.shape;sh.shapeType=ParticleSystemShapeType.Sphere;sh.radius=1;sh.radiusThickness=1;ps.useAutoRandomSeed=false;ps.randomSeed=42;var rows=new System.Collections.Generic.List<object>();foreach(float thickness in new[]{1f,.5f,.25f}){sh.radiusThickness=thickness;ps.Stop(false,ParticleSystemStopBehavior.StopEmittingAndClear);ps.randomSeed=42;ps.Simulate(0,false,true,false);ps.Emit(2048);var particles=new ParticleSystem.Particle[2048];var n=ps.GetParticles(particles);rows.Add(new{thickness,particles=particles.Take(n).Select(p=>new{position=new[]{p.position.x,p.position.y,p.position.z},radius=p.position.magnitude}).ToArray()});}System.IO.File.WriteAllText("OUTPUT_FILE",JsonConvert.SerializeObject(new{unityVersion=Application.unityVersion,seed=42,rows}));return "Native radius validation";}finally{Object.DestroyImmediate(go);}}}